    { name: 'Sh1RecursiveGenericRecord', typeParameters: ['T0'], recursiveFieldIndex: 1,
      fields: [{ name: 'item', type: parameterType },
        { name: 'next', type: namedType('Sh1RecursiveGenericRecord', ['T0']) }] },
  ];
  assert.deepEqual(value.layouts, layouts);
  const specs = [
